 static IEnumerable<TreeNode> Descend(TreeNodeCollection nodes){foreach(TreeNode n in nodes){yield return n;foreach(var child in Descend(n.Nodes))yield return child;}}
 void FindCard(){var tree=CardManager.Visible?CardManager:ListMods;var nodes=Descend(tree.Nodes).ToArray();if(nodes.Length==0)return;int start=Array.IndexOf(nodes,tree.SelectedNode);for(int i=1;i<=nodes.Length;i++){var node=nodes[(start+i+nodes.Length)%nodes.Length];if(node.Text.IndexOf(quickSearch.Text,StringComparison.OrdinalIgnoreCase)>=0){tree.SelectedNode=node;node.EnsureVisible();workspaceStatus.Text="Found: "+node.FullPath;return;}}workspaceStatus.Text="No matching mod, deck or card.";}
